  ('00000000-0000-4000-8000-000000002000', 'React Native & Next.js Developer', 'CyberSoft Vantage', 'Full-time', 'Islamabad, Pakistan', null, '2026-12-25', false, 'Building cross-platform mobile applications with React Native and production web applications with Next.js.', '{}'::text[], array['React Native', 'Next.js', 'TypeScript', 'Redux Toolkit', 'RTK Query']::text[], '{}'::text[], null, 0, true, '{"de":{"title":"React-Native- & Next.js-Entwickler","description":"Entwicklung plattformübergreifender mobiler Apps mit React Native und produktiver Webanwendungen mit Next.js."}}'::jsonb),
  ('00000000-0000-4000-8000-000000002001', 'MERN Stack Developer', 'CyberSoft Vantage', 'Full-time', 'Islamabad, Pakistan', null, null, false, 'Developed full-stack web applications with MongoDB, Express.js, React and Node.js, from REST APIs to dashboards.', '{}'::text[], array['MongoDB', 'Express.js', 'React.js', 'Node.js']::text[], '{}'::text[], null, 1, true, '{"de":{"title":"MERN-Stack-Entwickler","description":"Entwicklung von Full-Stack-Webanwendungen mit MongoDB, Express.js, React und Node.js, von REST-APIs bis zu Dashboards."}}'::jsonb),
  ('00000000-0000-4000-8000-000000002002', 'Angular Developer', 'CyberSoft Vantage', 'Full-time', 'Islamabad, Pakistan', null, null, false, 'Built frontend features and application interfaces with Angular and TypeScript.', '{}'::text[], array['Angular', 'TypeScript', 'Angular Signals']::text[], '{}'::text[], null, 2, true, '{"de":{"title":"Angular-Entwickler","description":"Umsetzung von Frontend-Features und Anwendungsoberflächen mit Angular und TypeScript."}}'::jsonb),
  ('00000000-0000-4000-8000-000000002003', 'Software Engineering Intern', 'CyberSoft Vantage', 'Internship', 'Islamabad, Pakistan', null, null, false, 'Started my professional journey, learning production workflows and contributing to web projects.', '{}'::text[], array['JavaScript', 'HTML5', 'CSS3', 'Git']::text[], '{}'::text[], null, 3, true, '{"de":{"title":"Praktikant Softwareentwicklung","description":"Einstieg ins Berufsleben: produktive Arbeitsabläufe kennengelernt und an Webprojekten mitgearbeitet."}}'::jsonb)
